<?php
namespace App\Http\Controllers;
use App\Http\Requests\{AssignTransportPassengerRequest,StoreTransportRouteStopRequest};use App\Models\{TransportPassenger,TransportRoute,TransportRouteStop};use App\Services\TransportAuditService;
class TransportRouteDetailController extends Controller {public function show(TransportRoute $transportRoute){$this->own($transportRoute);$transportRoute->load(['vehicle','driver.employee','monitor.employee','stops','passengers']);return view('transport.routes.show',['route'=>$transportRoute,'availablePassengers'=>TransportPassenger::forCompany(auth()->user()->company_id)->where('status','active')->orderBy('name')->get()]);}public function stop(StoreTransportRouteStopRequest $r,TransportRoute $transportRoute,TransportAuditService $audit){$this->own($transportRoute);$stop=$transportRoute->stops()->create($r->validated());$audit->record($transportRoute->company_id,'transport_route_stop_created','route_stop',$stop->id,$r->user()->id);return back()->with('success','Parada agregada.');}public function deleteStop(TransportRouteStop $stop,TransportAuditService $audit){$stop->load('route');$this->own($stop->route);abort_if($stop->route->passengers()->wherePivot('transport_route_stop_id',$stop->id)->exists(),422,'No puede eliminar una parada asignada a pasajeros.');$audit->record($stop->route->company_id,'transport_route_stop_deleted','route_stop',$stop->id,auth()->id());$stop->delete();return back()->with('success','Parada eliminada.');}public function assign(AssignTransportPassengerRequest $r,TransportRoute $transportRoute,TransportAuditService $audit){$this->own($transportRoute);$data=$r->validated();if(!empty($data['transport_route_stop_id']))abort_unless($transportRoute->stops()->whereKey($data['transport_route_stop_id'])->exists(),422,'La parada no pertenece a esta ruta.');$transportRoute->passengers()->attach($data['transport_passenger_id'],['transport_route_stop_id'=>$data['transport_route_stop_id']??null,'direction'=>$data['direction'],'valid_from'=>$data['valid_from'],'valid_until'=>$data['valid_until']??null,'status'=>$data['status']]);$audit->record($transportRoute->company_id,'transport_passenger_assigned','route',$transportRoute->id,$r->user()->id,['passenger_id'=>$data['transport_passenger_id']]);return back()->with('success','Pasajero asignado a la ruta.');}public function unassign(TransportRoute $transportRoute,TransportPassenger $passenger,TransportAuditService $audit){$this->own($transportRoute);abort_unless((int)$passenger->company_id===(int)auth()->user()->company_id,404);$transportRoute->passengers()->detach($passenger->id);$audit->record($transportRoute->company_id,'transport_passenger_unassigned','route',$transportRoute->id,auth()->id(),['passenger_id'=>$passenger->id]);return back()->with('success','Pasajero retirado de la ruta.');}private function own($m):void{abort_unless((int)$m->company_id===(int)auth()->user()->company_id,404);}}
